const state={data:null,lang:localStorage.getItem('opsie-lang')||'fr',dual:localStorage.getItem('opsie-dual')==='true',active:'home',progress:JSON.parse(localStorage.getItem('opsie-progress')||'{}'),answers:JSON.parse(localStorage.getItem('opsie-answers')||'{}')};
const UI={course:{fr:'LE COURS',ru:'КУРС'},localProgress:{fr:'Progression enregistrée sur cet appareil',ru:'Прогресс сохранён на этом устройстве'},dual:{fr:'Voir les deux langues',ru:'Показать оба языка'},pageConvention:{fr:'Pages PDF citées à partir de 1',ru:'Номера страниц PDF указаны с 1'},modules:{fr:'Modules du cours',ru:'Модули курса'},lessons:{fr:'leçons',ru:'уроков'},completed:{fr:'terminées',ru:'завершено'},score:{fr:'réponses justes',ru:'верных ответов'},focus:{fr:'À retravailler',ru:'Повторить'},schedule:{fr:'Plan de révision · 48 h',ru:'План подготовки · 48 ч'},exam:{fr:'Examen blanc',ru:'Пробный экзамен'},examIntro:{fr:'Questions inspirées des exercices et sujets fournis. Répondez en français.',ru:'Вопросы по упражнениям и экзаменационным темам из файлов. Отвечайте по-французски.'},sources:{fr:'Sources du cours',ru:'Источники курса'},quiz:{fr:'Vérifiez vos acquis',ru:'Проверьте знания'},check:{fr:'Vérifier ma réponse',ru:'Проверить ответ'},correct:{fr:'Bonne réponse',ru:'Верно'},incorrect:{fr:'À revoir',ru:'Нужно повторить'},finish:{fr:'Marquer la leçon terminée',ru:'Отметить урок завершённым'},next:{fr:'Leçon suivante →',ru:'Следующий урок →'},home:{fr:'Tableau de bord',ru:'Главная'},all:{fr:'Tout le cours',ru:'Весь курс'},openExam:{fr:'Passer l’examen blanc →',ru:'Перейти к экзамену →'},examSubmit:{fr:'Terminer et voir le bilan',ru:'Завершить и посмотреть результат'},examTimer:{fr:'Durée conseillée : 2 heures',ru:'Рекомендуемое время: 2 часа'},note:{fr:'À savoir',ru:'Обратите внимание'},review:{fr:'Revoir la leçon',ru:'Повторить урок'}};
function tx(x){if(typeof x==='string')return x||'';if(!x)return'';return state.dual&&x.ru?`${x.fr||''} / ${x.ru}`:(x[state.lang]||x.fr||'')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function t(k){return UI[k]?.[state.lang]||UI[k]?.fr||k}
function save(){localStorage.setItem('opsie-progress',JSON.stringify(state.progress));localStorage.setItem('opsie-answers',JSON.stringify(state.answers));localStorage.setItem('opsie-lang',state.lang);localStorage.setItem('opsie-dual',state.dual)}
function score(){let total=0,ok=0;for(const m of state.data.modules)for(let i=0;i<m.quiz.length;i++){const v=state.answers[`${m.id}:${i}`];if(v!==undefined){total++;const a=Array.isArray(v)?v:[v];if(JSON.stringify([...a].sort())===JSON.stringify([...m.quiz[i].answer].sort()))ok++}}return{total,ok}}
function renderNav(){const nav=document.querySelector('#lesson-nav');nav.innerHTML=`<button class="nav-item ${state.active==='home'?'active':''}" data-id="home"><span class="nav-num">⌂</span><span>${t('home')}</span><span></span></button>`+state.data.modules.map(m=>`<button class="nav-item ${state.active===m.id?'active':''}" data-id="${m.id}"><span class="nav-num">${m.n}</span><span>${esc(tx(m.title))}</span><span class="nav-check">${state.progress[m.id]?.done?'✓':''}</span></button>`).join('')+`<button class="nav-item ${state.active==='exam'?'active':''}" data-id="exam"><span class="nav-num">✦</span><span>${t('exam')}</span><span></span></button>`}
function renderRail(){const done=Object.values(state.progress).filter(x=>x.done).length,pct=Math.round(done/state.data.modules.length*100),s=score();const weak=state.data.modules.filter(m=>state.progress[m.id]?.wrong?.length).map(m=>`<button class="weak-link" data-id="${m.id}"><span>${esc(tx(m.title))} · ${state.progress[m.id].wrong.length}</span><b>↗</b></button>`).join('');document.querySelector('#rail').innerHTML=`<div class="rail-card"><h3>${t('all')}</h3><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="progress-copy">${done}/${state.data.modules.length} ${t('completed')} · ${pct}%</div><div class="stat-row"><div class="stat"><b>${s.ok}/${s.total||0}</b><span>${t('score')}</span></div><div class="stat"><b>${done}</b><span>${t('completed')}</span></div></div></div>${weak?`<div class="rail-card"><h3>${t('focus')}</h3><div class="weak-list">${weak}</div></div>`:''}<div class="rail-card"><h3>${t('schedule')}</h3>${state.data.course.plan48.map(x=>`<div class="schedule-item"><b>${esc(tx(x.h))}</b><span>${esc(tx(x.t))}</span></div>`).join('')}</div><div class="rail-card exam-banner"><h3>${t('exam')}</h3><p>${t('examIntro')}</p><button class="button" data-open="exam">${t('openExam')}</button></div>`}
function renderHome(){const done=Object.values(state.progress).filter(x=>x.done).length,s=score();return `<div class="eyebrow">${esc(tx(state.data.course.subtitle))}</div><h1>${esc(tx(state.data.course.title))}</h1><p class="subhead">${esc(tx(state.data.course.promise))}</p><div class="hero"><div class="eyebrow" style="color:#b8d4c3">48 HEURES · PARCOURS COMPLET</div><p>${state.lang==='fr'?'Un parcours guidé du droit d’auteur aux données personnelles. Des fiches courtes, des questions corrigées et un examen blanc en français.':'Полный маршрут: от авторского права до персональных данных. Короткие объяснения, проверка ответов и пробный экзамен на французском.'}</p></div><div class="section-head"><h2>${t('modules')}</h2><small>${state.data.modules.length} ${t('lessons')}</small></div><div class="stat-row"><div class="stat"><b>${done}/${state.data.modules.length}</b><span>${t('completed')}</span></div><div class="stat"><b>${s.ok}/${s.total||0}</b><span>${t('score')}</span></div><div class="stat"><b>13</b><span>${state.lang==='fr'?'supports analysés':'файлов изучено'}</span></div></div><div class="card"><h3>${t('note')}</h3>${state.data.course.notes.map(n=>`<p class="source-note">${esc(tx(n))}</p>`).join('')}</div><div class="section-head"><h2>${state.lang==='fr'?'Parcours conseillé':'Рекомендуемый маршрут'}</h2><small>${state.lang==='fr'?'ordre du plan enseignant':'по плану преподавателя'}</small></div>${state.data.modules.map(m=>`<div class="card lesson-card" data-id="${m.id}" style="cursor:pointer"><span class="pill">${m.n}</span><span class="pill">${m.part==='I'?'PARTIE I':m.part==='II'?'PARTIE II':state.lang==='fr'?'REPÈRES':'ОБЩЕЕ'}</span>${state.progress[m.id]?.done?'<span class="pill">✓</span>':''}<h3 style="margin-top:10px">${esc(tx(m.title))}</h3><p>${esc(tx(m.summary))}</p></div>`).join('')}<div class="section-head"><h2>${t('exam')}</h2></div><div class="card"><p>${t('examIntro')}</p><button class="button" data-open="exam">${t('openExam')}</button></div>`}
function renderLesson(m){const qs=m.quiz.map((q,i)=>{const v=state.answers[`${m.id}:${i}`],wrong=state.progress[m.id]?.wrong?.includes(i);return `<div class="quiz"><div class="quiz-prompt">${i+1}. ${esc(tx(q.prompt))}</div>${q.choices.map((c,j)=>`<label class="choice"><input type="${q.type==='multi'?'checkbox':'radio'}" name="q-${m.id}-${i}" value="${j}" ${Array.isArray(v)?v.includes(j)?'checked':'':v===j?'checked':''}><span>${esc(tx(c))}</span></label>`).join('')}<button class="button secondary" data-check="${i}">${t('check')}</button><div class="feedback ${v!==undefined?(wrong?'bad':'good'):'hide'}" data-feedback="${i}">${v!==undefined?`${wrong?t('incorrect'):t('correct')} · ${esc(tx(q.why))}`:''}</div></div>`}).join('');return `<div class="eyebrow">${state.lang==='fr'?'LEÇON':'УРОК'} ${m.n} · ${esc(m.part)}</div><h1>${esc(tx(m.title))}</h1><p class="subhead">${esc(tx(m.summary))}</p>${m.blocks.map(b=>`<article class="lesson-block"><h3>${esc(tx(b.h))}</h3><p>${esc(tx(b.t))}</p></article>`).join('')}<div class="example"><div class="eyebrow">${state.lang==='fr'?'EXEMPLE / POINT D’ATTENTION':'ПРИМЕР / ВАЖНО'}</div><p style="margin:7px 0 0">${esc(tx(m.example))}</p></div><div class="section-head"><h2>${t('quiz')}</h2><small>${m.quiz.length} ${state.lang==='fr'?'questions':'вопроса'}</small></div>${qs}<div class="section-head"><h2>${t('sources')}</h2></div><div class="card"><p class="source-note">${t('pageConvention')}</p><div class="source-list">${m.sources.map(s=>`<span class="source-chip">${esc(s.file)}${s.pages.length?' · '+(state.lang==='fr'?'p.':'с. ') +s.pages.join(', '):' · '+(state.lang==='fr'?'DOCX, sans pagination stable':'DOCX, без стабильной пагинации')}</span>`).join('')}</div></div><div class="section-head"><button class="button" data-done="${m.id}">${state.progress[m.id]?.done?'✓ ':''}${t('finish')}</button>${state.data.modules[state.data.modules.indexOf(m)+1]?`<button class="button secondary" data-next="${state.data.modules[state.data.modules.indexOf(m)+1].id}">${t('next')}</button>`:''}</div>`}
function renderExam(){const qs=state.data.exam.questions;return `<div class="eyebrow">OPSIE · ÉPREUVE D’ENTRAÎNEMENT</div><h1>${t('exam')}</h1><p class="subhead">${esc(tx(state.data.exam.description))} <span class="exam-timer">${t('examTimer')}</span></p><div class="card"><h3>${state.lang==='fr'?'Partie A · Questions de connaissances':'Часть A · Проверка знаний'}</h3>${qs.map((q,i)=>`<div class="quiz"><div class="quiz-prompt">${i+1}. ${esc(q.prompt.fr)}</div>${q.choices?q.choices.map((c,j)=>`<label class="choice"><input type="${q.type==='multi'?'checkbox':'radio'}" name="exam-q-${i}" value="${j}" ${((state.answers[`examq:${i}`]||[]).includes?.(j)||state.answers[`examq:${i}`]===j)?'checked':''}><span>${esc(c.fr)}</span></label>`).join(''):`<textarea data-exam="${i}" placeholder="Votre réponse en français…">${esc(state.answers[`exam:${i}`]||'')}</textarea>`}<button class="button secondary" data-exam-check="${i}">${t('check')}</button><div class="feedback hide" data-exam-feedback="${i}"></div><div class="source-list">${q.sources.map(s=>`<span class="source-chip">${esc(s.file)}${s.pages.length?' · p. '+s.pages.join(', '):''}</span>`).join('')}</div></div>`)}</div><div class="card"><h3>${state.lang==='fr'?'Corrigé indicatif':'Ориентировочные ответы'}</h3><p>${state.lang==='fr'?'Pour les réponses rédigées, la vérification automatique détecte des mots-clés. Ouvrez le corrigé après avoir répondu.':'Для открытых ответов система ищет ключевые слова. Откройте образец после того, как ответите.'}</p>${qs.filter(q=>q.model).map((q,i)=>`<details class="exam-question"><summary><b>${state.lang==='fr'?'Réponse modèle':'Образец ответа'} ${i+1}</b></summary><p>${esc(q.prompt.fr)}</p><p>${esc(q.model.fr)}</p><p class="source-note">${esc(q.why.fr)}</p></details>`).join('')}</div><button class="button" id="exam-finish">${t('examSubmit')}</button><div class="feedback hide" id="exam-result"></div>`}
function render(){renderNav();renderRail();const el=document.querySelector('#content');if(state.active==='home')el.innerHTML=renderHome();else if(state.active==='exam')el.innerHTML=renderExam();else{const m=state.data.modules.find(x=>x.id===state.active);el.innerHTML=m?renderLesson(m):renderHome()}document.querySelector('#crumb').textContent=state.active==='home'?t('home'):state.active==='exam'?t('exam'):tx(state.data.modules.find(m=>m.id===state.active)?.title);document.querySelector('#language').textContent=state.lang.toUpperCase()+'  ↔  '+(state.lang==='fr'?'RU':'FR');document.querySelector('#dual').classList.toggle('selected',state.dual);document.querySelector('[data-i18n="course"]').textContent=t('course');document.querySelector('[data-i18n="localProgress"]').textContent=t('localProgress');document.querySelector('footer [data-i18n="pageConvention"]').textContent=t('pageConvention')}
function open(id){state.active=id;document.querySelector('.sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function checkLessonQuestion(button){const m=state.data.modules.find(x=>x.id===state.active),i=+button.dataset.check,q=m.quiz[i],sel=[...document.querySelectorAll(`input[name="q-${m.id}-${i}"]:checked`)].map(x=>+x.value),ok=JSON.stringify([...sel].sort())===JSON.stringify([...q.answer].sort());state.answers[`${m.id}:${i}`]=q.type==='multi'?sel:sel[0];state.progress[m.id]??={done:false,wrong:[]};const p=state.progress[m.id];p.wrong=Array.isArray(p.wrong)?p.wrong:[];p.wrong=ok?p.wrong.filter(n=>n!==i):[...new Set([...p.wrong,i])];save();render()}
function checkExamQuestion(button){const i=+button.dataset.examCheck,q=state.data.exam.questions[i],f=document.querySelector(`[data-exam-feedback="${i}"]`);let ok=false,msg='';if(q.choices){const vals=[...document.querySelectorAll(`input[name="exam-q-${i}"]:checked`)].map(x=>+x.value);state.answers[`examq:${i}`]=q.type==='multi'?vals:vals[0];ok=JSON.stringify([...vals].sort())===JSON.stringify([...q.answer].sort());msg=tx(q.why)}else{const val=(state.answers[`exam:${i}`]||'').toLowerCase();ok=q.keywords.some(k=>val.includes(k.toLowerCase()));msg=ok?tx(q.why):`${tx(q.why)} · ${tx(q.model)}`}save();f.className='feedback '+(ok?'good':'bad');f.textContent=`${ok?t('correct'):t('incorrect')} · ${msg}`}
function finishExam(){let total=0,ok=0;state.data.exam.questions.forEach((q,i)=>{if(q.choices){total++;const v=state.answers[`examq:${i}`],a=Array.isArray(v)?v:[v];if(JSON.stringify([...a].sort())===JSON.stringify([...q.answer].sort()))ok++}});const r=document.querySelector('#exam-result');r.className='feedback '+(ok>=total*.6?'good':'bad');r.textContent=`${state.lang==='fr'?'Résultat automatique':'Автоматический результат'} : ${ok}/${total} ${state.lang==='fr'?'QCM corrects. Les questions ouvertes sont vérifiées par mots-clés.':'верных ответов в тесте. В открытых заданиях проверяются ключевые слова.'}`;r.scrollIntoView({behavior:'smooth',block:'center'})}
function bindEvents(){document.addEventListener('click',e=>{const target=e.target.closest('button,[data-id],[data-check],[data-done],[data-next],[data-exam-check],[data-open]');if(!target)return;if(target.id==='language'){state.lang=state.lang==='fr'?'ru':'fr';save();render();return}if(target.id==='dual'){state.dual=!state.dual;save();render();return}if(target.id==='menu-toggle'){document.querySelector('.sidebar').classList.toggle('open');return}if(target.dataset.check!==undefined){checkLessonQuestion(target);return}if(target.dataset.done){state.progress[target.dataset.done]??={done:false,wrong:[]};state.progress[target.dataset.done].done=true;save();render();return}if(target.dataset.next){open(target.dataset.next);return}if(target.dataset.examCheck!==undefined){checkExamQuestion(target);return}if(target.id==='exam-finish'){finishExam();return}if(target.dataset.open){open(target.dataset.open);return}if(target.dataset.id){open(target.dataset.id);return}});document.addEventListener('input',e=>{if(e.target.matches('[data-exam]')){state.answers[`exam:${e.target.dataset.exam}`]=e.target.value;save()}})}
async function init(){bindEvents();const response=await fetch('content/course.json');state.data=await response.json();render()}
init().catch(e=>{document.querySelector('#content').innerHTML='<h1>Contenu indisponible</h1><p>Le fichier course.json ne peut pas être chargé.</p>'});
